"""Weekly timesheet lines built from a list of shifts."""

from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift
from hourglass.errors import ProjectError


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("shift has no worker name")


def _totals(shifts: List[Shift]) -> Dict[str, List[int]]:
    """Shift count and minutes for each worker."""
    totals = {}
    for shift in shifts:
        entry = totals.setdefault(shift.worker, [0, 0])
        entry[0] += 1
        entry[1] += shift.span.minutes
    return totals


def _rank(item: Tuple[str, List[int]]) -> tuple:
    name, (count, minutes) = item
    return (-minutes, -count, name)


def _line(name: str, count: int, minutes: int) -> str:
    word = "shift" if count == 1 else "shifts"
    hours = f"{minutes / 60:.1f}"
    return f"{name}: {count} {word}, {hours} hours"


def timesheet_lines(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, most hours first.

    Raises ProjectError for no shifts or a blank worker name.
    """
    shifts = list(shifts)
    _check(shifts)
    ranked = sorted(_totals(shifts).items(), key=_rank)
    return [_line(name, *data) for name, data in ranked]

